  approve(previewId,{decision='APPROVE',selectedSteps,actor={type:'user',id:'local'}}={}){const preview=this.previews.get(previewId)||this.previewEngine.branches.get(previewId)?.preview;if(!preview)throw new AICommandError('PREVIEW_NOT_FOUND','Cannot approve missing preview');if(decision!=='APPROVE'&&decision!=='REJECT')throw new AICommandError('APPROVAL_INVALID','Decision must be APPROVE or REJECT');const approval={format:'INK-AI-APPROVAL',version:1,approvalId:uid('approval'),previewId,planId:preview.planId,recipeId:preview.recipeId,decision,selectedSteps:clone(selectedSteps||preview.steps),actor:clone(actor),baseDocumentHash:preview.baseDocumentHash,timestamp:now()};this.approvals.set(approval.approvalId,approval);if(decision==='REJECT')this.previewEngine.discard(previewId);return clone(approval);}
