  executeApproval(approvalId){const started=performance.now?.()||Date.now(),approval=this.approvals.get(approvalId);if(!approval||approval.decision!=='APPROVE')throw new AICommandError('APPROVAL_REQUIRED','A valid explicit approval is required');const plan=this.plans.get(approval.planId);if(!plan||plan.confidence<this.policy.confidenceThreshold)throw new AICommandError('LOW_CONFIDENCE','Execution confidence is below policy threshold',{confidence:plan?.confidence??null,threshold:this.policy.confidenceThreshold});const current=this.currentDocument(),preview=this.previews.get(approval.previewId);if(!preview)throw new AICommandError('PREVIEW_NOT_FOUND','Approved preview is unavailable');if(hashValue(current)!==approval.baseDocumentHash)throw new AICommandError('DOCUMENT_VERSION_MISMATCH','Document changed after preview or approval',{expected:approval.baseDocumentHash,actual:hashValue(current)});const recipe=this.recipes.get(approval.recipeId),checkpointId=uid('checkpoint'),before=clone(current);current.ai=current.ai||{};current.ai.checkpoints=current.ai.checkpoints||[];current.ai.checkpoints.push({checkpointId,label:`Before ${recipe.recipeId}`,timestamp:now(),documentHash:hashValue(current),snapshot:checkpointSnapshot(current)});const effects=[];try{for(const step of recipe.steps.filter(x=>approval.selectedSteps.includes(x.stepId))){if(this.cancelled.has(recipe.recipeId))throw new AICommandError('USER_CANCELLED','Execution was cancelled');effects.push({stepId:step.stepId,...this.executor.apply(current,step.operation,step.target,step.parameters,{seed:recipe.seed})});}current.ai.recipes=current.ai.recipes||[];current.ai.recipes.push({...clone(recipe),status:'EXECUTED',approvalId,checkpointId});current.modifiedAt=now();const difference=collectChanges(before,current),execution={format:'INK-AI-EXECUTION',version:1,executionId:uid('execution'),recipeId:recipe.recipeId,planId:recipe.planId,approvalId,checkpointId,status:'COMPLETED',beforeHash:hashValue(before),afterHash:hashValue(current),effects,difference,rollbackAvailable:true,timestamp:now()};this.executions.set(execution.executionId,{...clone(execution),before});this.setDocument(current);const audit=this.audit.add({actor:approval.actor,permissionLevel:'EXECUTE',planId:recipe.planId,recipeId:recipe.recipeId,targetIds:recipe.steps.flatMap(x=>asArray(x.target)),commands:recipe.steps.map(x=>x.operation),previewGenerated:preview.previewId,userDecision:'APPROVE',executionResult:execution,checkpoint:checkpointId,differenceSummary:difference,duration:(performance.now?.()||Date.now())-started,securityEvents:['SAFE']});this.currentDocument().ai=this.currentDocument().ai||{};this.currentDocument().ai.audit=this.audit.list();return{...clone(execution),auditId:audit.auditId};}catch(error){for(const key of Object.keys(current))delete current[key];Object.assign(current,before);const audit=this.audit.add({actor:approval.actor,permissionLevel:'EXECUTE',planId:recipe.planId,recipeId:recipe.recipeId,userDecision:'APPROVE',error:{code:error.code||'EXECUTION_FAILED',message:error.message},rollbackStatus:'COMPLETED',duration:(performance.now?.()||Date.now())-started});throw Object.assign(error,{auditId:audit.auditId});}}
  rollback(executionId){const entry=this.executions.get(executionId);if(!entry?.before)throw new AICommandError('EXECUTION_NOT_FOUND','Execution rollback source not found');const current=this.currentDocument(),difference=collectChanges(current,entry.before);this.setDocument(clone(entry.before));entry.status='ROLLED_BACK';entry.rollbackStatus='COMPLETED';const audit=this.audit.add({permissionLevel:'EXECUTE',planId:entry.planId,recipeId:entry.recipeId,commands:['recipe.rollback'],checkpoint:entry.checkpointId,differenceSummary:difference,rollbackStatus:'COMPLETED',executionResult:{executionId,status:'ROLLED_BACK'}});return{executionId,status:'ROLLED_BACK',documentHash:hashValue(this.currentDocument()),auditId:audit.auditId,difference};}
