export class ChatIntegrationAdapter {
  constructor(layer,{clientVersion=AI_LAYER_VERSION,clientId='local-json'}={}){this.layer=layer;this.clientVersion=clientVersion;this.clientId=clientId;this.active=new Map();}
  negotiate(request={}){return{format:'INK-CHAT-NEGOTIATION',requestId:request.requestId||uid('request'),clientId:this.clientId,...this.layer.manifest.negotiate({clientVersion:request.version||this.clientVersion,operations:request.operations||[]}),schemas:{command:'ink-ai-command-v1',capability:'ink-ai-capability-manifest-v1',documentState:'ink-document-state-v1',plan:'ink-editable-plan-v1',preview:'ink-ai-preview-v1',approval:'ink-ai-approval-v1',execution:'ink-ai-execution-v1',result:'ink-ai-result-v1',error:'ink-ai-error-v1',audit:'ink-ai-audit-v1'}};}
  async request(envelope,{onProgress,signal}={}){const requestId=envelope.requestId||uid('request'),controller=new AbortController(),started=Date.now();this.active.set(requestId,controller);const timeout=setTimeout(()=>controller.abort('timeout'),Math.min(300000,envelope.timeout||30000));const combined=signal||controller.signal;try{onProgress?.({requestId,phase:'VALIDATING',progress:.1});const result=await this.layer.dispatch({...envelope.command,requestId},{idempotencyKey:envelope.idempotencyKey,signal:combined});onProgress?.({requestId,phase:result.status==='FAILED'?'FAILED':'COMPLETED',progress:1});return{format:'INK-CHAT-RESULT',version:AI_LAYER_VERSION,requestId,sessionId:envelope.sessionId||envelope.command?.sessionId,status:result.status,partial:false,duration:Date.now()-started,...result};}finally{clearTimeout(timeout);this.active.delete(requestId);}}
  cancel(requestId){const controller=this.active.get(requestId);if(!controller)return{requestId,cancelled:false};controller.abort('user');return{requestId,cancelled:true};}
}

export class LocalJSONCommandClient { constructor(adapter){this.adapter=adapter;} send(json,options){const envelope=typeof json==='string'?JSON.parse(json):json;return this.adapter.request(envelope,options);} }
export class DeterministicTestClient { constructor(adapter,{seed=1500}={}){this.adapter=adapter;this.seed=seed;} plan(text,options={}){return this.adapter.request({requestId:`det-${hashValue([text,this.seed])}`,idempotencyKey:`det-${hashValue([text,this.seed])}`,command:createCommand('recipe.createDraft',{permissionLevel:'PROPOSE',deterministicSeed:this.seed,parameters:{input:text,type:'text',options:{...options,seed:this.seed}}})});} }
export class MockAIClient { constructor(adapter){this.adapter=adapter;this.semanticMaturity='NOT CLAIMED';} sendFixture(envelope,options){return this.adapter.request({...clone(envelope),mockTransportOnly:true},options);} }
export class ManualCommandConsole { constructor(localClient){this.localClient=localClient;} execute(text,options){return this.localClient.send(text,options);} }
